using Ses.Core;
using System.Text;

int checks = 0, failures = 0;
void Check(string name, Action test) { checks++; try { test(); Console.WriteLine("PASS " + name); } catch (Exception ex) { failures++; Console.WriteLine("FAIL " + name + ": " + ex.Message); } }
void Assert(bool value) { if (!value) throw new Exception("assertion failed"); }
void Reject(Action test) { try { test(); } catch (InvalidDataException) { return; } throw new Exception("invalid input accepted"); }
Check("Veylo accepts legacy startup targets without accepting arbitrary executables",()=>{
    const string legacy="\"C:\\Old\\SES.exe\" --minimized";
    const string current=@"C:\Apps\Veylo\Veylo.exe";
    Assert(StartupRegistration.TryGetTarget("\""+current+"\" --minimized",out string target)&&target==current);
    Assert(StartupRegistration.TryUpgrade(legacy,current,new(0,6,11),new(0,6,12))=="\""+current+"\" --minimized");
    Assert(StartupRegistration.TryUpgrade("\""+current+"\" --minimized",@"C:\Old\SES.exe",new(0,6,12),new(0,6,11)) is null);
    foreach(string executable in new[]{@"C:\Apps\Veylo.exe.bat",@"C:\Apps\other.exe",@"\\server\share\Veylo.exe",@"C:\Apps\Veylo.exe:payload"})
        Assert(!StartupRegistration.TryGetTarget("\""+executable+"\" --minimized",out _));
});
Check("startup upgrade recognizes only the exact enabled local SES command",()=>{
    const string path=@"C:\Program Files\SES 0.1.0\SES.exe";
    Assert(StartupRegistration.TryGetTarget("\""+path+"\" --minimized",out string target)&&target==path);
    foreach(string? command in new string?[]{null,"","\"","\" --minimized","\"\" --minimized","SES.exe --minimized",path+" --minimized","\""+path+"\"", "\""+path+"\" --minimized --other","\""+path+"\"  --minimized"," \""+path+"\" --minimized","\""+path+"\" --minimized\n","\"C:\\other.exe\" --minimized","\"relative\\SES.exe\" --minimized"}){
        Assert(!StartupRegistration.TryGetTarget(command,out target)&&target=="");
        Assert(StartupRegistration.TryUpgrade(command,@"C:\Current\SES.exe",new(0,1,0),new(0,6,8)) is null);
    }
});
Check("startup upgrade rejects unsafe Windows targets before metadata lookup",()=>{
    foreach(string path in new[]{@"\\server\share\SES.exe",@"\\?\C:\SES.exe",@"C:SES.exe",@"C:\Old\..\SES.exe",@"C:\.\SES.exe",@"C:\Old.\SES.exe",@"C:\Old \SES.exe",@"C:\Old\\SES.exe",@"C:\Old\SES.exe:payload",@"C:/Old/SES.exe","C:\\Old\n\\SES.exe","C:\\Old\"\\SES.exe",@"C:\Old*\SES.exe",@"C:\Old|\SES.exe",@"C:\Old?\SES.exe"}){
        Assert(!StartupRegistration.TryGetTarget("\""+path+"\" --minimized",out _));
        Assert(StartupRegistration.TryUpgrade("\"C:\\Old\\SES.exe\" --minimized",path,new(0,1,0),new(0,6,8)) is null);
    }
});
Check("startup upgrade preserves absence and unknown versions",()=>{
    const string saved="\"C:\\Old\\SES.exe\" --minimized";
    Assert(StartupRegistration.TryUpgrade(saved,@"C:\Current\SES.exe",null,new(0,6,8)) is null);
    Assert(StartupRegistration.TryUpgrade(saved,@"C:\Current\SES.exe",new(0,1,0),null) is null);
    Assert(StartupRegistration.TryUpgrade(saved,null!,new(0,1,0),new(0,6,8)) is null);
});
Check("startup upgrade selects newer explicitly launched SES without downgrading",()=>{
    const string saved="\"C:\\Old\\SES.exe\" --minimized";const string current=@"D:\Apps\SES 0.6.8\SES.exe";
    foreach(var old in new[]{new Version(0,1,0),new Version(0,6,0),new Version(0,6,7),new Version(0,6,8),new Version(0,6,8,0)})
        Assert(StartupRegistration.TryUpgrade(saved,current,old,new(0,6,8))=="\""+current+"\" --minimized");
    foreach(var old in new[]{new Version(0,6,8,1),new Version(0,6,9),new Version(1,0)})
        Assert(StartupRegistration.TryUpgrade(saved,current,old,new(0,6,8)) is null);
    Assert(StartupRegistration.TryUpgrade(saved,@"c:\old\ses.EXE",new(0,1,0),new(0,6,8)) is null);
});
