Check("live validation diagnostic cadence derives only from low overhead mode",()=>{
    var normal=new LiveValidationOptions(30,false);var low=normal with{LowOverhead=true};
    Assert(!normal.LowOverhead&&normal.PollIntervalMilliseconds==100&&normal.ProgressIntervalSeconds==10);
    Assert(low.PollIntervalMilliseconds==1000&&low.ProgressIntervalSeconds==30);
    Assert(LiveValidationOptions.Parse(["--validate-live"])==normal);
});
