float[] PersonalSample(float amplitude=.08f,float ambient=.0005f,float bass=1)
{
    var data=new float[AudioSamples.MaxFrames];var random=new Random(83);
    for(int i=0;i<data.Length;i++){
        double seconds=i/(double)AudioSamples.Rate;
        float level=seconds<5?0:seconds<12?amplitude:seconds<16?amplitude*.45f:amplitude*1.8f;
        double voice=bass*Math.Sin(i*2*Math.PI*170/48000)+.35*Math.Sin(i*2*Math.PI*900/48000)+.18*Math.Sin(i*2*Math.PI*2800/48000);
        data[i]=level*(float)voice+ambient*(float)(random.NextDouble()-.5);
    }
    return data;
}
Check("personal calibration tailors gain limits to quieter microphones",()=>{var quiet=PersonalCalibration.Analyze(PersonalSample(.015f));var loud=PersonalCalibration.Analyze(PersonalSample(.15f));Assert(quiet.Success&&loud.Success);Assert(quiet.Settings!.MaxGainDb>loud.Settings!.MaxGainDb);Assert(quiet.Settings.TargetDb==-20&&quiet.Settings.OutputDb==0);});
Check("personal calibration responds to ambient noise and remains conservative",()=>{var quiet=PersonalCalibration.Analyze(PersonalSample());var noisy=PersonalCalibration.Analyze(PersonalSample(.08f,.012f));Assert(quiet.Success&&noisy.Success);Assert(noisy.Settings!.NoiseMix>quiet.Settings!.NoiseMix);Assert(noisy.Settings.NoiseAutoEnabled&&noisy.Settings.Bands.All(b=>Math.Abs(b.GainDb)<=2));noisy.Settings.Validate();});
