Check("personal calibration requires speech in every prompted section",()=>{var x=PersonalSample();Array.Clear(x,12*48000,4*48000);Assert(PersonalCalibration.Analyze(x).Error=="autoQuietMissing");x=PersonalSample();Array.Clear(x,16*48000,4*48000);Assert(PersonalCalibration.Analyze(x).Error=="autoLoudMissing");Assert(!PersonalCalibration.Analyze(new float[AudioSamples.MaxFrames]).Success);});
