Check("talk modes preserve manual mute and fail closed before first key press",()=>{Assert(ShortcutSettings.Muted(1,false,false));Assert(!ShortcutSettings.Muted(1,true,false));Assert(ShortcutSettings.Muted(1,true,true));Assert(ShortcutSettings.Muted(2,true,false));Assert(!ShortcutSettings.Muted(2,false,false));Assert(!ShortcutSettings.Muted(0,false,false));Assert(ShortcutSettings.Muted(0,true,true));});
Check("shortcut plans validate collisions and retain fixed factory identifiers",()=>{Reject(()=>new ShortcutSettings(TalkMode:3).Validate());Reject(()=>new ShortcutSettings(TalkMode:1,HoldKey:"M").Validate());Reject(()=>new ShortcutSettings(HoldKey:"F12").Validate());var bindings=new ShortcutSettings(PresetKeys:true).Bindings();Assert(bindings['1']=="natural"&&bindings['5']=="podcast"&&bindings.Count==7);Assert(new ShortcutSettings().Bindings().Count==2);});
Check("hotkey conflicts roll back new reservations without losing old bindings",()=>{var registered=new Dictionary<int,int>();var released=new List<int>();int conflict=-1;using var registry=new HotkeyRegistry((id,key)=>{if(key==conflict)return false;registered.Add(id,key);return true;},id=>{released.Add(id);registered.Remove(id);});Assert(registry.Apply(new()));var old=registered.ToDictionary(x=>x.Key,x=>x.Value);conflict='Z';Assert(!registry.Apply(new("X","Z",1,"T",true)));Assert(registered.Count==2&&old.All(x=>registered[x.Key]==x.Value));Assert(registry.ActionFor(old.Single(x=>x.Value=='M').Key)=="mute");Assert(released.Count==1);});
Check("hotkey reconfiguration reuses chords atomically and unregisters removed chords",()=>{var registered=new Dictionary<int,int>();using var registry=new HotkeyRegistry((id,key)=>{Assert(!registered.ContainsValue(key));registered.Add(id,key);return true;},id=>registered.Remove(id));Assert(registry.Apply(new(PresetKeys:true)));Assert(registry.Apply(new("B","M",2,"T")));Assert(registered.Count==3);Assert(registry.ActionFor(registered.Single(x=>x.Value=='B').Key)=="mute");Assert(registry.ActionFor(registered.Single(x=>x.Value=='M').Key)=="bypass");for(int i=0;i<100;i++)Assert(registry.Apply(new(i%2==0?"X":"Y","B")));Assert(registered.Count==2);registry.Dispose();Assert(registered.Count==0);});
