Check("game polling matches custom executable suffixes without changing exclusions",()=>{
    var policy=new GameModePolicy();
    Assert(policy.Update(true,new[]{new GameObservation("CustomGame")},new[]{"customgame.EXE"},0));
    Assert(policy.DetectedName=="CustomGame");
    policy.Update(false,Array.Empty<GameObservation>(),Array.Empty<string>(),1);
    Assert(!policy.Update(true,new[]{new GameObservation("chrome",true)},new[]{"customgame.EXE"},2));
    Assert(policy.Update(true,new[]{new GameObservation("chrome",true)},new[]{"Chrome.EXE"},3));
    Assert(!GameModePolicy.ValidProcessName(".hidden")&&!GameModePolicy.ValidProcessName("trailing ")&&!GameModePolicy.ValidProcessName("path/name"));
    Assert(GameModePolicy.ValidProcessName("Türkçe-Oyun_2.exe"));
});
Check("game span matcher preserves validation normalization precedence and first match",()=>{
    foreach(var name in new string?[]{null,"",".hidden","trailing ","path/name","path\\name","nul\0name",new('a',97)}){
        Assert(!GameModePolicy.ValidProcessName(name)&&!GameModePolicy.Matches(name.AsSpan(),true,Array.Empty<string>()));
    }
    foreach(string name in new[]{"a",new string('a',96),"Türkçe-Oyun_2.exe"})Assert(GameModePolicy.ValidProcessName(name)&&GameModePolicy.Matches(name.AsSpan(),true,Array.Empty<string>()));
    Assert(GameModePolicy.Matches("Cs2.EXE".AsSpan(),false,Array.Empty<string>()));
    Assert(!GameModePolicy.Matches("Chrome.EXE".AsSpan(),true,Array.Empty<string>()));
    Assert(GameModePolicy.Matches("Chrome.EXE".AsSpan(),false,new[]{"chrome"}));
    var policy=new GameModePolicy();
    Assert(policy.Update(true,new[]{new GameObservation("chrome",true),new GameObservation("FirstGame.exe"),new GameObservation("cs2")},new[]{"firstgame"},0));
    Assert(policy.DetectedName=="FirstGame");
    GameModePolicy.ValidateNames(new(){new('a',96),"Türkçe-Oyun_2.exe"});
    Reject(()=>GameModePolicy.ValidateNames(new(){new('a',97)}));Reject(()=>GameModePolicy.ValidateNames(new(){"nul\0name"}));
});
Check("game unmatched span polling does not allocate process-name strings",()=>{
    var custom=new[]{"CustomGame.EXE"};
    for(int i=0;i<100;i++)Assert(!GameModePolicy.Matches("NormalBackground.exe".AsSpan(),false,custom));
    long before=GC.GetAllocatedBytesForCurrentThread();bool matched=false;
    for(int i=0;i<10000;i++)matched|=GameModePolicy.Matches("NormalBackground.exe".AsSpan(),false,custom);
    long allocated=GC.GetAllocatedBytesForCurrentThread()-before;
    Assert(!matched&&allocated==0);
});
Console.WriteLine($"{checks} tests, {failures} failures");return failures==0?0:1;
